mat3 rotate3D(float angle, vec3 axis){
    vec3 a = normalize(axis);
    float s = sin(angle);
    float c = cos(angle);
    float r = 1.0 - c;
    return mat3(
        a.x * a.x * r + c,
        a.y * a.x * r + a.z * s,
        a.z * a.x * r - a.y * s,
        a.x * a.y * r - a.z * s,
        a.y * a.y * r + c,
        a.z * a.y * r + a.x * s,
        a.x * a.z * r + a.y * s,
        a.y * a.z * r - a.x * s,
        a.z * a.z * r + c
    );
}


void mainImage( out vec4 o, in vec2 FC)
{
float i,j,d=.4,e,t=iTime; vec3 p,q=vec3(1,2,0),r=iResolution;
o=vec4(0.);

for(i=0.;i++<64.&&d>1e-4;){
    p=vec3((FC.xy-.5*r.xy)/r.y,e);
    p.z-=4.;
    p*=rotate3D(t*.3,q);

    for(j=0.;j++<12.;)
        p=abs(p*rotate3D(3.41,q)-.04)-.05,
        d=max(max(p.y,p.x), p.z),
        d-=dot(p,p)/1e4;

    e+=d;

}o=vec4(sqrt(p*i)*e,1)*e;
}
